	mldsa44PublicKeyHex  = ""
	mldsa44Seed1Hex      = "0101010101010101010101010101010101010101010101010101010101010101"
	mldsa44PublicKey1Hex = ""
	mldsa44Seed2Hex      = "0202020202020202020202020202020202020202020202020202020202020202"
	mldsa44PublicKey2Hex = ""

	// Seed and public keys generated using ML-DSA-65.
	mldsa65SeedHex       = "dddaccfaa05b0332b3fd7269c7d42de6cbe370735431f735346ccb6be7ad3174"
	mldsa65PublicKeyHex = ""

	mldsa65Seed1Hex      = "0101010101010101010101010101010101010101010101010101010101010101"
	mldsa65PublicKey1Hex = ""

	mldsa65Seed2Hex      = "0202020202020202020202020202020202020202020202020202020202020202"
	mldsa65PublicKey2Hex = ""

	// Seed and public keys generated using ML-DSA-87.
	mldsa87SeedHex       = "dddaccfaa05b0332b3fd7269c7d42de6cbe370735431f735346ccb6be7ad3174"
	mldsa87PublicKeyHex = ""

	mldsa87Seed1Hex      = "0101010101010101010101010101010101010101010101010101010101010101"
